head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > P > keepDataType]<br/>dataType 속성값이 숫자형('number', 'bigDecimal')인 Column 에 데이터 설정 시 자동 형변환을 할지 설정합니다.",
    "validation" : [
        "바인드 된 GridView 또는 set 계열의 메소드로 설정 시에도 적용됩니다.",
        "바인드 된 GridView 는 부호문자('+','-'), 소숫점('.'), 숫자 등의 숫자 관련 문자만 입력할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // 조건 설정       
    let properties = {
        keepDataType: con_keepDataType.getText(),   
        preserveType: con_preserveType.getText(),
    };    

    let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strGridView = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:dataList ' + strNameSpace + ' ' + cList + ' id="target1" baseNode="list" repeatNode="map">';        
    strTarget += '<w2:columnInfo>';
    strTarget += '<w2:column id="col1" name="name1" dataType="number"></w2:column>';
    strTarget += '<w2:column id="col2" name="name2" dataType="text"></w2:column>';
    strTarget += '<w2:column id="col3" name="name3" dataType="text"></w2:column>';
    strTarget += '</w2:columnInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '</w2:data>';
    strTarget += '</w2:dataList>';     

    // target 생성
    $p.data.create(strTarget);

    // gridView 생성    
    strGridView += '<w2:gridView ' + strNameSpace + ' dataList="data:target1" rowStatusVisible="true" checkAllType="false" id="" style="width:500px;height:300px;">';
    strGridView += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strGridView += '<w2:header style="" id="header1">';
    strGridView += '<w2:row style="" id="row1">';
    strGridView += '<w2:column width="70" style="" inputType="text" id="column1" value="number"></w2:column>';
    strGridView += '<w2:column width="70" style="" inputType="text" id="column2" value="text"></w2:column>';
    strGridView += '<w2:column width="70" style="" inputType="text" id="column3" value="text"></w2:column>';
    strGridView += '</w2:row>';
    strGridView += '</w2:header>';
    strGridView += '<w2:gBody style="" id="gBody1">';
    strGridView += '<w2:row style="" id="row2">';
    strGridView += '<w2:column width="70" style="" inputType="text" id="col1" value=""></w2:column>';
    strGridView += '<w2:column width="70" style="" inputType="text" id="col2" value=""></w2:column>';
    strGridView += '<w2:column width="70" style="" inputType="text" id="col3" value=""></w2:column>';
    strGridView += '</w2:row>';
    strGridView += '</w2:gBody>';
    strGridView += '</w2:gridView>';    

    scwin["gridView1"] = await $p.dynamicCreate(
        "gridView1",
        "gridView",
        strGridView,
        grp_comp
    );
}



scwin.btn_getAllJSON_onclick = function (e) {
    let rtn = target1.getAllJSON();
    let jsonString = JSON.stringify(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);
};



scwin.btn_setJSON_onclick = function (e) {   
    let jsonData = [
        {col1:"111", col2:111, col3:"111"},
        {col1:"test", col2:111, col3:"111"}
    ];

    target1.setJSON(jsonData, true);

    scwin.btn_getAllJSON_onclick();
};
